import { ANALYTICS, ANALYTICS_CSP_ORIGINS } from "@/src/config/analytics";

/**
 * Build a per-request policy. The nonce is generated by proxy.ts and also
 * forwarded on the request so Next.js can nonce its own framework scripts.
 */
export function buildContentSecurityPolicy(nonce: string): string {
    const connectSources = ["'self'"];
    const scriptSources = ["'self'", `'nonce-${nonce}'`, "'strict-dynamic'"];

    if (process.env.NEXT_PUBLIC_SUPABASE_URL) {
        try {
            const supabaseOrigin = new URL(process.env.NEXT_PUBLIC_SUPABASE_URL).origin;
            connectSources.push(supabaseOrigin, "wss://*.supabase.co");
        } catch {
            // Ignore malformed optional configuration; env validation handles it separately.
        }
    }

    if (ANALYTICS.ga4Id || ANALYTICS.gtmId) {
        scriptSources.push(...ANALYTICS_CSP_ORIGINS.script);
        connectSources.push(...ANALYTICS_CSP_ORIGINS.connect);
    }

    if (ANALYTICS.metaPixelId) {
        scriptSources.push("https://connect.facebook.net");
        connectSources.push("https://www.facebook.com");
    }

    return [
        "default-src 'self'",
        `script-src ${scriptSources.join(" ")}`,
        // Tailwind/theme custom properties still use inline style attributes.
        "style-src 'self' 'unsafe-inline'",
        "img-src 'self' data: blob: https:",
        "font-src 'self' data:",
        `connect-src ${connectSources.join(" ")}`,
        "media-src 'self'",
        "object-src 'none'",
        "base-uri 'self'",
        "form-action 'self'",
        "frame-ancestors 'none'",
        "upgrade-insecure-requests",
    ].join("; ");
}
